<script lang="ts">import {getContext} from 'svelte';import {page} from '$app/state';import type {I18nState} from '../../../../../lib/i18n/i18n.svelte';import {createInventoryAdjustmentsState} from '../state/inventoryAdjustmentsState.svelte';import type {CreateInventoryAdjustment} from '../../domain/entity/InventoryAdjustment';const i18n=getContext<I18nState>('i18n');const selection=getContext<{warehouseId:number|null}>('warehouseSelection');const vm=createInventoryAdjustmentsState();const approvals= $derived(page.params.feature==='count-approvals');let open=$state(false),itemId=$state(''),binId=$state(''),quantity=$state('1'),reason=$state(''),type=$state<'ADD'|'REMOVE'>('ADD');$effect(()=>{const mode=approvals,warehouseId=selection?.warehouseId;void vm.load(warehouseId??null,mode);});async function create(){const v:CreateInventoryAdjustment={itemId:Number(itemId),binId:Number(binId),warehouseId:selection?.warehouseId??0,type,quantity:Number(quantity),reason};if(await vm.create(v,selection?.warehouseId??null)){open=false;itemId='';binId='';quantity='1';reason='';}}async function decide(id:number,action:'approve'|'reject'){await vm.review([{adjustmentId:id,action}],selection?.warehouseId??null);}</script>
<section class="page"><header><div><p class="eyebrow">ABELLIS · SMART WMS</p><h1>{approvals?i18n.t('Aprobación de conteos'):i18n.t('Ajustes de inventario')}</h1><p>{approvals?i18n.t('Revisa diferencias pendientes; aprobar modifica las existencias.'):i18n.t('Consulta el historial y registra correcciones directas de inventario.')}</p></div>{#if !approvals}<button class="primary" onclick={()=>open=!open}>{i18n.t('Nuevo ajuste')}</button>{/if}</header>{#if vm.error}<p class="error" role="alert">{vm.error}</p>{/if}
{#if open}<form class="editor" onsubmit={e=>{e.preventDefault();void create();}}><label>{i18n.t('ID de producto')}<input type="number" min="1" required bind:value={itemId}/></label><label>{i18n.t('ID de ubicación')}<input type="number" min="1" required bind:value={binId}/></label><label>{i18n.t('Tipo')}<select bind:value={type}><option value="ADD">{i18n.t('Añadir')}</option><option value="REMOVE">{i18n.t('Retirar')}</option></select></label><label>{i18n.t('Cantidad')}<input type="number" min="1" required bind:value={quantity}/></label><label class="wide">{i18n.t('Motivo')}<input required maxlength="500" bind:value={reason}/></label><div class="actions"><button type="button" onclick={()=>open=false}>{i18n.t('Cancelar')}</button><button class="primary" disabled={vm.saving||!selection?.warehouseId}>{i18n.t('Guardar')}</button></div></form>{/if}
{#if vm.loading}<p>{i18n.t('Cargando…')}</p>{:else}<div class="table-wrap"><table><thead><tr><th>{i18n.t('Ajuste')}</th><th>SKU</th><th>{i18n.t('Producto')}</th><th>{i18n.t('Ubicación')}</th><th>{i18n.t('Esperado')}</th><th>{i18n.t('Contado')}</th><th>{i18n.t('Variación')}</th><th>{i18n.t('Motivo')}</th><th>{i18n.t('Estado')}</th><th>{i18n.t('Registrado por')}</th>{#if approvals}<th>{i18n.t('Acciones')}</th>{/if}</tr></thead><tbody>{#each vm.rows as r (r.adjustmentId)}<tr><td>{r.adjustmentId}</td><td>{r.sku??'—'}</td><td>{r.itemName??r.itemId}</td><td>{r.binCode??r.binId}</td><td>{r.expectedQuantity??'—'}</td><td>{r.countedQuantity??'—'}</td><td>{r.quantityChange>0?'+':''}{r.quantityChange}</td><td>{r.reasonDetail??r.reasonCode}</td><td>{r.status}</td><td>{r.adjustedBy}</td>{#if approvals}<td><button class="primary" onclick={()=>void decide(r.adjustmentId,'approve')}>{i18n.t('Aprobar')}</button><button class="danger" onclick={()=>void decide(r.adjustmentId,'reject')}>{i18n.t('Rechazar')}</button></td>{/if}</tr>{/each}</tbody></table></div>{/if}</section>
<style>.page{max-width:78rem;margin:1.4rem auto;padding:0 1.1rem;color:var(--ink)}header{display:flex;justify-content:space-between;align-items:center;gap:1rem;margin-bottom:1rem}h1{margin:0;font:700 1.6rem var(--disp)}header p{color:var(--slate);font-size:.9rem}.eyebrow{font:600 .65rem var(--disp);letter-spacing:.14em}button{border:1px solid var(--line);border-radius:8px;padding:.5rem .7rem;background:var(--card);color:var(--ink);cursor:pointer}.primary{background:var(--navy);color:white;border-color:var(--navy)}.danger,.error{color:var(--danger)}.editor{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.7rem;padding:1rem;border:1px solid var(--line);border-radius:12px;background:var(--card)}.editor h2,.wide,.actions{grid-column:1/-1}.editor label{display:grid;gap:.3rem;color:var(--slate);font-size:.8rem}.editor input,.editor select{min-height:39px;border:1px solid var(--line);border-radius:8px;padding:.5rem .65rem;background:var(--card);color:var(--ink)}.actions{display:flex;justify-content:flex-end}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:12px;background:var(--card);margin:1rem 0}table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:.82rem}th,td{text-align:left;padding:.65rem;border-bottom:1px solid var(--line)}th{color:var(--slate);font-size:.7rem;text-transform:uppercase}@media(max-width:640px){header{align-items:flex-start;flex-direction:column}.editor{grid-template-columns:1fr}}</style>